--
-- Name: item_groups_with_count; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.item_groups_with_count AS
 SELECT ig.id,
    ig.group_code,
    ig.group_name,
    ig.description,
    ig.parent_group_id,
    ig.is_active,
    ig.organization_id,
    ig.created_at,
    ig.updated_at,
    ig.status,
    COALESCE(p.product_count, (0)::bigint) AS product_count
   FROM (public.item_groups ig
     LEFT JOIN ( SELECT products.category_id,
            count(*) AS product_count
           FROM public.products
          WHERE (products.status = 1)
          GROUP BY products.category_id) p ON ((ig.id = p.category_id)))
  ORDER BY ig.created_at DESC;


